// === Tab: mySketch ===
const cp = [
  "#F5EAEA",
  "#FFB84C",
  "#F16767",
  "#A459D1",
  "#4D455D",
  "#E96479",
  "#F5E9CF",
  "#7DB9B6",
];
let f = 0;
let n;
let t;
let w;
let x, y;
let seed;
let isNight = true;
let items = [];

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
  angleMode(DEGREES);
  blendMode(REPLACE);

  for (let i = 0; i < 50; i++) {
    items.push({
      x: random(-width / 2, width / 2),
      y: random(-height / 2, height / 2),
      s: random(0.8, 1.2),
      v: random([-1, 1]) * random(1, 5),
      c: random(cp),
    });
  }
}

function draw() {

// [SENTINEL 專家 2 修復] 音訊座標數值防禦
if(typeof window.simulatedMouseX === 'number' && isNaN(window.simulatedMouseX)) window.simulatedMouseX = width*0.5;
if(typeof window.simulatedMouseY === 'number' && isNaN(window.simulatedMouseY)) window.simulatedMouseY = height*0.5;

  background(isNight ? 50 : 255);

  for (let item of items) {
    let p = map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, -2, 2);
    item.v += p / 20;
    drawUmbrella(item.x, item.y, item.v, item.s, item.c);
  }
}

function drawUmbrella(initX, initY, v, s, c) {
  translate(initX, initY);
  // rotateX(frameCount * v);
  rotateY(frameCount * v);
  // rotateZ(frameCount * v);
  scale(s);

  push();
  fill(isNight ? 255 : c);
  noStroke();
  beginShape();
  for (let i = 180; i < 360; i += 6) {
    x = 100 * cos(i);
    y = 90 * sin(i);
    vertex(x, y);
  }
  for (let j = 100; j > -100; j -= 40) {
    for (let i = 360; i > 180; i -= 6) {
      x = j - 20 + 20 * cos(i);
      y = 20 * sin(i);
      vertex(x, y);
    }
  }
  endShape(CLOSE);
  pop();

  push();
  stroke(isNight ? width : c);
  strokeWeight(4);
  // draw stick
  line(0, -110, 0, 50);

  // draw handle
  noFill();
  arc(-7.5, 50, 15, 20, 0, 180);
  pop();

  // rotateZ(-frameCount * v);
  rotateY(-frameCount * v);
  // rotateX(-frameCount * v);
  translate(-initX, -initY);
}

function mousePressed() {
  isNight = !isNight;
}

